-- STEP 62 (APPLIED 2026-10-21): Sunyani Technical University, 34 HND rows (Regular, Weekend, Evening for six programmes), 15 diplomas and 18 CTVET craft certificates (Certificate level). Short courses not loaded. Source: https://www.stu.edu.gh/images/documents/admissions/STU_Admissions_2025-2026.pdf . All unverified.
with v(name, field, mode, level, kind) as (values
 ('HND Accountancy','Business','Regular','Diploma','h'),
 ('HND Accountancy','Business','Weekend','Diploma','h'),
 ('HND Accountancy','Business','Evening','Diploma','h'),
 ('HND Computerized Accounting','Business','Regular','Diploma','h'),
 ('HND Computerized Accounting','Business','Weekend','Diploma','h'),
 ('HND Computerized Accounting','Business','Evening','Diploma','h'),
 ('HND Marketing','Business','Regular','Diploma','h'),
 ('HND Marketing','Business','Weekend','Diploma','h'),
 ('HND Marketing','Business','Evening','Diploma','h'),
 ('HND Purchasing and Supply','Business','Regular','Diploma','h'),
 ('HND Purchasing and Supply','Business','Weekend','Diploma','h'),
 ('HND Purchasing and Supply','Business','Evening','Diploma','h'),
 ('HND Secretaryship and Management Studies','Business','Regular','Diploma','h'),
 ('HND Secretaryship and Management Studies','Business','Weekend','Diploma','h'),
 ('HND Secretaryship and Management Studies','Business','Evening','Diploma','h'),
 ('HND Hotel, Catering and Institutional Management','Business','Regular','Diploma','h'),
 ('HND Hotel, Catering and Institutional Management','Business','Weekend','Diploma','h'),
 ('HND Hotel, Catering and Institutional Management','Business','Evening','Diploma','h'),
 ('HND Welding and Metallurgical Engineering','Engineering','Regular','Diploma','h'),
 ('HND Civil Engineering','Engineering','Regular','Diploma','h'),
 ('HND Electrical/Electronics Engineering','Engineering','Regular','Diploma','h'),
 ('HND Materials Engineering','Engineering','Regular','Diploma','h'),
 ('HND Mechanical Engineering (Automobile Option)','Engineering','Regular','Diploma','h'),
 ('HND Mechanical Engineering (Plant Option)','Engineering','Regular','Diploma','h'),
 ('HND Mechanical Engineering (Production Option)','Engineering','Regular','Diploma','h'),
 ('HND Building Technology','Engineering','Regular','Diploma','h'),
 ('HND Ceramic Arts','Arts','Regular','Diploma','h'),
 ('HND Fashion Design Technology','Arts','Regular','Diploma','h'),
 ('HND Textiles Technology','Arts','Regular','Diploma','h'),
 ('HND Interior Design and Technology (Wood Technology)','Arts','Regular','Diploma','h'),
 ('HND Computer Science','Computing','Regular','Diploma','h'),
 ('HND Dispensing Technology','Health','Regular','Diploma','h'),
 ('HND General Agriculture','Agriculture','Regular','Diploma','h'),
 ('HND Information and Communication Technology','Computing','Regular','Diploma','h'),
 ('Diploma in Real Estate','Business','Regular','Diploma','d5'),
 ('Diploma in Computerised Accounting','Business','Regular','Diploma','d5'),
 ('Diploma in Banking Technology and Accounting','Business','Regular','Diploma','d5'),
 ('Diploma in Electronic Marketing','Business','Regular','Diploma','d5'),
 ('Diploma in Business Administration','Business','Regular','Diploma','d5'),
 ('Diploma in Public Relations','Business','Regular','Diploma','d5'),
 ('Diploma in Procurement and Materials Management','Business','Regular','Diploma','d4'),
 ('Diploma in Business Studies (Accounting Option)','Business','Regular','Diploma','d4'),
 ('Diploma in Business Studies (Secretarial Option)','Business','Regular','Diploma','d4'),
 ('Diploma in Business Studies (Management Option)','Business','Regular','Diploma','d4'),
 ('Diploma in Business Studies (Marketing Option)','Business','Regular','Diploma','d4'),
 ('Diploma in Business Studies (Purchasing and Supply)','Business','Regular','Diploma','d4'),
 ('Diploma in Business Studies (Statistics Option)','Science','Regular','Diploma','d4'),
 ('Diploma in Business Studies (Entrepreneurship Option)','Business','Regular','Diploma','d4'),
 ('Professional Diploma in Computerised Accounting','Business','Regular','Diploma','dp'),
 ('National Proficiency I in Garment Making','Arts','Regular','Certificate','c'),
 ('National Proficiency I in Automotive Engineering Technology','Engineering','Regular','Certificate','c'),
 ('National Proficiency I in Block Laying and Tiling','Engineering','Regular','Certificate','c'),
 ('National Proficiency I in Welding and Fabrication','Engineering','Regular','Certificate','c'),
 ('National Proficiency I in Electrical Installation','Engineering','Regular','Certificate','c'),
 ('National Proficiency I in Plumbing','Engineering','Regular','Certificate','c'),
 ('National Certificate I in Garment Making','Arts','Regular','Certificate','c'),
 ('National Certificate I in Electrical Engineering Technology','Engineering','Regular','Certificate','c'),
 ('National Certificate I in Block Laying and Tiling','Engineering','Regular','Certificate','c'),
 ('National Certificate I in Automotive Mechanic','Engineering','Regular','Certificate','c'),
 ('National Certificate I in Furniture Design Technology','Engineering','Regular','Certificate','c'),
 ('National Certificate I in Welding and Fabrication Technology','Engineering','Regular','Certificate','c'),
 ('National Certificate I in Building Construction Technology','Engineering','Regular','Certificate','c'),
 ('National Certificate I in Electronics Engineering Technology','Engineering','Regular','Certificate','c'),
 ('National Certificate I in Poultry Production','Agriculture','Regular','Certificate','c'),
 ('National Certificate I in Computer Data Administration','Computing','Regular','Certificate','c'),
 ('National Certificate I in Computer Networking System','Computing','Regular','Certificate','c'),
 ('National Certificate I in Computer Software Development','Computing','Regular','Certificate','c')),
s as (select id from public.schools where name = 'Sunyani Technical University'),
ins as (
  insert into public.programs (school_id, name, level, field, mode, verified, demo, entry_note)
  select s.id, v.name, v.level, v.field, v.mode, false, false,
   case v.kind
    when 'h' then 'UNVERIFIED. Listed in the STU 2025/2026 admissions document (https://www.stu.edu.gh/images/documents/admissions/STU_Admissions_2025-2026.pdf). Entry rule: SSSCE credits A to D, or WASSCE credits A1 to C6 in electives (core range given as A1 to D7), in English Language, Mathematics and Integrated Science or Social Studies plus three relevant electives; other routes (Certificate II, A Level, technical school, DBS holders, mature applicants 25+) are in the document. No aggregate is stated.'
    when 'd5' then 'UNVERIFIED. Listed in the STU 2025/2026 admissions document (https://www.stu.edu.gh/images/documents/admissions/STU_Admissions_2025-2026.pdf), 2-year diploma. Entry rule: five SSSCE or WASSCE passes including English Language and Mathematics, or GBCE passes. No aggregate is stated.'
    when 'd4' then 'UNVERIFIED. Listed in the STU 2025/2026 admissions document (https://www.stu.edu.gh/images/documents/admissions/STU_Admissions_2025-2026.pdf). Entry rule: four SSSCE or WASSCE passes including English Language and Mathematics, or GBCE passes. No aggregate is stated. Diploma in Business Studies options are listed as 1-year, the others as 2-year.'
    when 'dp' then 'UNVERIFIED. Listed in the STU 2025/2026 admissions document (https://www.stu.edu.gh/images/documents/admissions/STU_Admissions_2025-2026.pdf). Entry requires a Diploma in Computerised Accounting. No aggregate is stated.'
    else 'UNVERIFIED. CTVET craft certificate listed in the STU 2025/2026 admissions document (https://www.stu.edu.gh/images/documents/admissions/STU_Admissions_2025-2026.pdf). The document states no entry requirement or aggregate. Certificate application form costs GHS 100.' end
  from v cross join s where not exists (select 1 from public.programs p where p.school_id = s.id and p.name = v.name and p.level = v.level and p.mode = v.mode) returning id, name, mode),
rq as (insert into public.program_requirements (program_id, subject, min_grade, is_core) select i.id, x.subject, case when v.kind = 'h' then 'D7' else 'E8' end, true from ins i join v on v.name = i.name and v.mode = i.mode and v.kind in ('h','d5','d4') cross join (values ('Core Mathematics'),('English Language')) x(subject) returning 1)
select (select count(*) from ins) as programs, (select count(*) from rq) as requirements;
